use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}

impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}

impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}

impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn report<T: Shape>(s: T) -> int {
    let d = s.double_area()
    println("${s.name()} corners=${s.corners()} area2=${d}")
    d
}

fn num(p: Vec<string>, i: int) -> int {
    if i < p.len() as int {
        p[i].parse::<int>().unwrap_or(0)
    } else {
        0
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = 0
    let mut best_name = "none"
    let mut count = 0
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 {
            continue
        }
        let kind = p[0]
        let mut d = -1
        let mut nm = ""
        if kind == "square" {
            d = report(Square { s: num(p, 1) })
            nm = "square"
        } else if kind == "rect" {
            d = report(Rect { w: num(p, 1), h: num(p, 2) })
            nm = "rect"
        } else if kind == "rtri" {
            d = report(Rtri { a: num(p, 1), b: num(p, 2) })
            nm = "rtri"
        } else if kind == "trap" {
            d = report(Trap { a: num(p, 1), b: num(p, 2), h: num(p, 3) })
            nm = "trap"
        }
        if d >= 0 {
            total += d
            if count == 0 || d > best {
                best = d
                best_name = nm
            }
            count += 1
        }
    }
    println("total area2=${total}")
    if count == 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

